nd:#edf8f0; font-size:12px; }.division-form { margin-top:24px; }.two-columns { display:grid; grid-template-columns:1fr 1fr; gap:20px; }.compact-control :deep(.el-select),.compact-control :deep(.el-input-number) { width:260px; max-width:100%; }.generated-division-name { display:grid; grid-template-columns:112px auto 1fr; align-items:center; gap:12px; min-height:46px; margin-top:2px; padding:0 14px; border:1px solid #cfe4d6; border-radius:7px; background:#f5fbf7; }.generated-division-name span { color:#64736a; font-size:13px; }.generated-division-name strong { color:#087c43; font-size:16px; }.generated-division-name small { color:#7a867e; font-size:12px; }.mode-section { margin-top:20px; padding-top:22px; border-top:1px solid #edf1ee; }.mode-cards { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-top:18px; }.mode-card { display:flex; align-items:center; gap:12px; width:100%; padding:16px; border:1px solid #dce6df; border-radius:10px; color:inherit; text-align:left; background:#fff; cursor:pointer; transition:.18s ease; }.mode-card:hover,.mode-card.selected { border-color:#26a867; background:#f6fcf8; box-shadow:0 0 0 3px rgba(29,158,88,.09); }.mode-icon { display:grid; width:37px; height:37px; place-items:center; border-radius:10px; font-size:19px; }.mode-icon.green { color:#07884a; background:#e9f8ed; }.mode-icon.orange { color:#e9830b; background:#fff2df; }.mode-card span:nth-child(2) { min-width:0; flex:1; }.mode-card strong,.mode-card small { display:block; }.mode-card strong { font-size:14px; }.mode-card small { overflow:hidden; margin-top:5px; color:#7a877f; font-size:12px; text-overflow:ellipsis; white-space:nowrap; }.choice { color:#0b9a52; font-size:19px; }.preview-column { display:flex; width:340px; flex-direction:column; gap:16px; }.preview-card { padding:25px; }.preview-label { margin:0 0 22px; color:#7c897f; font-size:13px; }.preview-name { display:flex; gap:13px; align-items:center; padding-bottom:22px; border-bottom:1px solid #edf1ee; }.preview-name>span { display:grid; width:46px; height:46px; place-items:center; color:#087c42; background:transparent; font-size:23px; }.preview-name h2 { margin:0; font-size:22px; }.preview-name p { margin:5px 0 0; color:#76847b; font-size:13px; }.preview-card dl { margin:18px 0 0; }.preview-card dl>div { display:flex; justify-content:space-between; padding:10px 0; }.preview-card dt { color:#7b887f; font-size:13px; }.preview-card dd { margin:0; color:#2c3c32; font-weight:600; font-size:13px; }.preview-card dd.simple { color:#17814a; }.preview-card dd.professional { color:#d97400; }.preview-card dd.draft { color:#ae7218; }.hint-card { display:flex; gap:10px; padding:16px; color:#65766b; background:#fbfdfb; font-size:13px; line-height:1.65; }.hint-card .el-icon { flex:0 0 auto; margin-top:3px; color:#1b9755; font-size:17px; }.hint-card p { margin:0; }.action-bar { position:fixed; z-index:10; right:0; bottom:0; left:var(--admin-sidebar-width, 0px); display:flex; min-height:82px; align-items:center; justify-content:space-between; padding:17px 28px; border-top:1px solid #e3eae5; background:rgba(255,255,255,.98); box-shadow:0 -7px 22px rgba(28,52,37,.04); }.action-bar>span { color:#3f4e45; font-size:14px; }.action-bar>div { display:flex; gap:10px; }.action-bar :deep(.el-button--primary) { min-width:360px; min-height:54px; font-size:17px; }.permission-alert { margin-top:16px; } @media (max-width:1220px) { .header-meta { display:none; }.create-grid { grid-template-columns:800px; }.preview-column { display:grid; grid-template-columns:1fr 1fr; width:800px; max-width:100%; }.action-bar { padding-inline:24px; } } @media (max-width:860px) { .create-grid { grid-template-columns:minmax(0,1fr); }.form-panel { width:100%; }.preview-column { width:100%; }.two-columns,.mode-cards,.preview-column { grid-template-columns:1fr; }.generated-division-name { grid-template-columns:1fr; gap:4px; padding:10px 12px; }.form-panel { padding:22px; }.action-bar { left:0; padding:14px 18px; }.action-bar>span { display:none; } }
